import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 107 · Christmas recipe: cornbread dressing

sc("""Sweetheart, cornbread dressing is the dish that disappears first from every Christmas table I've ever sat at. Golden and crispy on top, soft and savory inside, full of sage and onion and celery. But most of the dressing I taste is either dry as sawdust or a soggy, mushy brick. And it's always the same five mistakes. Every one of them is easy to fix.""",
   "pan of golden cornbread dressing", "DRY OR MUSHY?")
sc("""So tonight I'm giving you the cornbread dressing my mother made every Christmas on Elm Street, step by step. And stay with me, because the last secret is one thing she did the night before, with a plain kitchen towel, that made hers the best in the whole church, and nobody ever guessed it.""",
   "kitchen towel over pan of cornbread", "THE NIGHT BEFORE")

ch("Dressing or stuffing")
sc("""First, honey, let's settle the argument. Stuffing goes inside the bird. Dressing is baked in its own pan. Up North, most families say stuffing either way, and down South, they say dressing either way, and they've been arguing about it for a hundred years. My mother's people came from Kentucky, so in our house it was always dressing, and it was always cornbread. Never white bread.""",
   "roasted turkey beside baking dish of dressing", "DRESSING, NOT STUFFING")
sc("""Cornbread dressing goes back to the Native peoples of the South, who were baking cornmeal long before any settlers arrived. Poor Southern families made it because cornmeal was cheap and wheat flour wasn't. You used yesterday's cornbread, a few vegetables, and whatever broth you had. It was a way of making a little bit of meat feed a whole family at Christmas. In a minute I'll tell you why the old cornbread matters so much.""",
   "cast iron skillet of cornbread old kitchen", "YESTERDAY'S CORNBREAD")
sc("""My mother made a double batch every Christmas, honey. One pan for us, and one pan for the Lutheran church supper on Christmas Eve. And every year, Mrs. Hartley, who thought she was the best cook in Mansfield, would take a big spoonful, chew it slowly, and say, Dorothy, what's in this? And my mother would just smile and say, love, Margaret. Just love. She never told her about the towel.""",
   "church supper table with covered dishes 1950s", "JUST LOVE")

sc("""I learned to make it standing on a wooden chair next to her, when I was seven. My job was crumbling the cornbread. Danny's job was tearing the white bread, and he always ate half of it. My mother would say, Daniel, if you eat the glue, the whole thing falls apart. We didn't know what she meant by glue for years. I'll tell you exactly what she meant in a minute.""",
   "little girl on chair crumbling cornbread", "DON'T EAT THE GLUE")
ch("What you need")
sc("""Here's what you need for a nine by thirteen pan. One big pan of cornbread, about eight cups crumbled, made a day ahead. Four slices of white sandwich bread, torn up and dried. One stick of butter. Two cups of chopped onion, and two cups of chopped celery. Two eggs. About four cups of chicken or turkey broth. And two tablespoons of fresh sage, or two teaspoons dried.""",
   "dressing ingredients on kitchen counter", "WHAT YOU NEED")
sc("""Plus a teaspoon of dried thyme, a teaspoon of black pepper, and salt to taste. Some families add a little cooked sausage or chopped boiled egg. My mother added neither, because the cornbread and the sage were the whole show. And one very important thing, honey. The cornbread must not be sweet. Sweet cornbread makes dessert dressing. Use buttermilk cornbread, with no sugar, or just a tablespoon at the most.""",
   "unsweetened buttermilk cornbread in skillet", "NOT SWEET")

sc("""And the cornbread itself is simple, honey. Two cups of yellow cornmeal, one cup of flour, a tablespoon of baking powder, a teaspoon of salt, two eggs, two cups of buttermilk, and a half stick of melted butter. Heat your cast iron skillet in a four hundred twenty-five degree oven with a spoonful of bacon grease, pour the batter into the hot pan so it sizzles, and bake about twenty-five minutes.""",
   "batter poured into sizzling cast iron skillet", "IT HAS TO SIZZLE")
ch("Mistake one")
sc("""Mistake number one is using fresh cornbread. Fresh cornbread is full of moisture, and when you pour broth over it, it collapses into mush. That's why so many people's dressing is a soggy brick. You want the cornbread stale, honey. Bake it the day before. Crumble it into big pieces. And leave it out on a sheet pan overnight, uncovered, so it dries out. Remember that, because it's connected to the secret.""",
   "crumbled cornbread drying on sheet pan", "STALE, NOT FRESH")
sc("""If Grandma's recipe is helping you, tap the like button for me, sweetheart. It helps more people find these videos. Mistake number two is skipping the white bread. Cornbread alone falls apart. A few slices of torn, dried white bread act like glue. They hold it together so you can cut a nice square, instead of scooping crumbs. My mother always used four slices, the heels of the loaf, which nobody wanted anyway.""",
   "torn white bread pieces in bowl", "THE GLUE")

ch("Mistake three and four")
sc("""Mistake number three is raw vegetables. If you throw raw onion and celery into the pan, they never soften all the way, and you get crunchy bits in soft dressing. Melt the whole stick of butter in a skillet, and cook the onion and celery slowly, over medium heat, for ten or twelve minutes, until they're soft and sweet and just starting to turn gold. Then stir in the sage and thyme for one more minute.""",
   "onions and celery softening in butter skillet", "COOK THEM FIRST")
sc("""Mistake number four is pouring in all the broth at once. Every pan of cornbread is different, honey. Some soak up more, some less. So put your crumbled cornbread and bread in your biggest bowl. Pour the butter and vegetables over the top. Then add three cups of warm broth, stir gently, and squeeze a handful. It should feel like a wet sponge. Not dripping, not crumbly. Add the last cup a little at a time.""",
   "hand squeezing moist dressing mixture", "LIKE A WET SPONGE")
sc("""Taste it now, before the eggs go in. This is your only chance, honey. Add salt and pepper until it tastes a little too seasoned, because the baking will mellow it. Then beat the two eggs and fold them in gently with your hands. The eggs are what make it set into a soft, sliceable dressing instead of a pile of crumbs. Don't stir it hard, or you'll mash it.""",
   "folding eggs into dressing by hand", "TASTE BEFORE THE EGGS")

ch("Mistake five")
sc("""So far, stale cornbread, a little white bread for glue, soft vegetables, and broth added slowly until it feels like a sponge. Mistake number five is packing it down. People press their dressing into the pan like they're laying bricks. Then it bakes into a dense, heavy slab. Grease your pan with butter and spoon the dressing in loosely. Leave the top rough and bumpy, honey. Those bumps are what turn crispy.""",
   "dressing spooned loosely into buttered pan", "DON'T PACK IT")
sc("""Dot the top with a few little pieces of cold butter. Bake it uncovered at three hundred seventy-five degrees for about forty to forty-five minutes, until the top is deep golden brown and the edges pull away from the pan. If you like it extra crispy, slide it under the broiler for the last two minutes. And let it rest ten minutes before you cut it. Stay with me, because now comes the secret.""",
   "dressing baking golden in oven", "375 FOR 45 MINUTES")

ch("The secret")
sc("""Here's my mother's secret, sweetheart. The night before, when she crumbled her cornbread onto the sheet pan to dry, she didn't just leave it bare. She sprinkled it with a little of the dried sage and a pinch of salt. Then she laid a clean kitchen towel loosely over the top, so the dust couldn't get in but the air still could. And she let it sit on top of the warm stove all night.""",
   "kitchen towel over cornbread on stove", "THE TOWEL")
sc("""By morning, the sage had soaked into every crumb, and the cornbread had dried just enough. So the flavor wasn't just in the broth, honey. It was in the bread itself. That's why Mrs. Hartley could never figure it out. Hers tasted like sage on the outside. My mother's tasted like sage all the way through. And it held the broth perfectly, without ever turning to mush.""",
   "close up of dressing with sage inside", "SAGE ALL THE WAY THROUGH")

sc("""One more thing, sweetheart. Don't use plain water instead of broth, no matter what anybody tells you. Water makes it taste flat, like wet bread. If you have time, simmer the turkey neck and giblets in a pot of water with an onion and a celery stalk while the bird roasts. That homemade broth is liquid gold. If you don't have time, a good boxed broth is just fine. Mother would forgive you.""",
   "pot of homemade turkey broth simmering", "LIQUID GOLD")
ch("Make it ahead")
sc("""You can make it a day ahead, honey, which saves your sanity on Christmas morning. Mix everything except the eggs, cover it, and keep it in the refrigerator overnight. In the morning, fold in the eggs, spoon it into the pan, and bake. Give it an extra ten minutes, because it's cold. Leftovers keep four days, and a square fried in butter the next morning with a fried egg on top is my favorite breakfast of the whole year.""",
   "fried square of dressing with egg breakfast", "BEST BREAKFAST OF THE YEAR")
sc("""When my mother passed, in nineteen eighty-nine, Susan was the one who asked for her recipe card. It just says, cornbread dressing, in Mother's handwriting, with the ingredients, and at the bottom, in pencil, one word. Towel. Nobody knew what it meant except me. Now Susan knows. And so do you, honey.""",
   "old handwritten recipe card with pencil note", "ONE WORD: TOWEL")

ch("Grandma's kitchen")
sc("""Make it this Christmas, sweetheart, and watch it disappear first. Tell me in the comments, does your family say stuffing or dressing? I want to settle this once and for all. There are more of my Christmas recipes in the playlist right there on your screen. Good night, honey. Merry Christmas.""",
   "Christmas dinner table with dressing and turkey", "STUFFING OR DRESSING?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma107", "Cornbread Dressing EVERYONE's Grandma Made (Why Yours Is MUSHY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Cornmeal dishes in the American South descend from Native American corn cookery; cornbread dressing became a Southern holiday staple because cornmeal was cheaper than wheat flour.",
      "Recipe as written by Grandma Ruth: 8 cups stale unsweetened cornbread, 4 slices dried white bread, 1 stick butter, 2 cups onion, 2 cups celery, 2 tbsp fresh sage, 1 tsp thyme, 1 tsp pepper, salt, about 4 cups broth, 2 eggs; 375F for 40-45 minutes uncovered."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
